def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Gather simple stats
    my_c = 0
    opp_c = 0
    cc = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1
        if a == 'C' and b == 'C':
            cc += 1
    my_d = n - my_c
    opp_d = n - opp_c

    last_me, last_opp = history[-1]

    # Early: be nice but retaliate immediately once.
    if n < 3:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # If opponent is clearly mostly cooperative, keep cooperating;
    # but near the end, exploit reliably if they never retaliate.
    if opp_d == 0:
        return 'C'

    # If opponent is very defective recently, defect to avoid being exploited.
    if n >= 5:
        recent = history[-5:]
        recent_opp_d = 0
        for a, b in recent:
            if b == 'D':
                recent_opp_d += 1
        if recent_opp_d >= 4:
            return 'D'

    # If opponent rarely defects, forgive to maintain CC.
    if opp_d * 5 <= n:
        # One-time defection: forgive mostly, but if last two opponent moves are D, punish.
        if last_opp == 'D':
            if n >= 2 and history[-2][1] == 'D':
                return 'D'
            return 'C'
        return 'C'

    # Moderate defection rate: tit-for-tat with a little forgiveness.
    if last_opp == 'D':
        # If we defected last time too and opponent has defected a lot, keep defecting.
        if last_me == 'D' and opp_d * 2 >= n:
            return 'D'
        # If opponent's recent behavior is mostly D, defect.
        if n >= 4:
            r = history[-4:]
            rd = 0
            for a, b in r:
                if b == 'D':
                    rd += 1
            if rd >= 3:
                return 'D'
        # Otherwise punish once, then likely return to C next turn.
        return 'D'

    # Opponent cooperated last move.
    if last_me == 'D':
        # If we just defected and opponent still cooperated, go back to C
        # unless opponent is extremely cooperative and we are ahead.
        if opp_d * 3 <= n:
            return 'C'
        # Against mostly cooperative, occasionally exploit near end.
        if n >= 90 and opp_d * 4 <= n:
            return 'D' if rng.random() < 0.5 else 'C'
        return 'C'

    # Default: cooperate.
    # Near the end, if opponent is moderately cooperative and never punishes,
    # defect a bit to exploit.
    if n >= 92:
        if opp_d * 3 <= n:
            return 'D'
        if opp_d * 2 <= n:
            return 'D' if rng.random() < 0.25 else 'C'
    return 'C'
